/* @lc app=leetcode id=2661 lang=kotlin */ class Solution { fun firstCompleteIndex(arr: IntArray, mat: Array<IntArray>): Int = HashMap<Int, Pair<Int, Int>>().also { m -> mat.indices.forEach { i -> mat[0].indices.forEach { j -> m[mat[i][j]] = i to j } } }.let { pos -> IntArray(mat.size).let { rc -> IntArray(mat[0].size).let { cc -> arr.indices.first { k -> pos[arr[k]]!!.let { (r, c) -> ++rc[r] == mat[0].size || ++cc[c] == mat.size } } } } } }